CHECK_CPP2V_ROCQC_ARGS="-w -notation-overridden -w -notation-incompatible-prefix"

sayDo() {
    echo "$@"
    eval "$*"
}

# Keep transcripts independent of generated adapter paths and execution mode.
# cpp2v_command is generated by cpp2v-toolchain and declared by a setup script.
sayDo_cpp2v() {
    echo "cpp2v $*"
    eval "cpp2v_command $*"
}

check_cpp2v_versions() {
    input="$1"
    base="${input%.*}"

    shift
    for ver in "$@"
    do
        # Avoid spurious spaces if CRAM_CPP2VFLAGS/CRAM_CXXFLAGS are empty
        sayDo_cpp2v "-v -check-types -o ${base}_${ver}_cpp.v ${input}${CRAM_CPP2VFLAGS:+ ${CRAM_CPP2VFLAGS}} -- -std=c++${ver}${CRAM_CXXFLAGS:+ ${CRAM_CXXFLAGS}} 2>&1 | sed 's/^ *[0-9]* | //'"
        sayDo "rocq c ${CHECK_CPP2V_ROCQC_ARGS} ${base}_${ver}_cpp.v"
    done
}

check_cpp2v() {
    check_cpp2v_versions "$1" 17
}

check_cpp2v_templates_versions() {
    input="$1"
    base="${input%.*}"

    shift
    for ver in "$@"
    do
        # Avoid spurious spaces if CRAM_CPP2VFLAGS/CRAM_CXXFLAGS are empty
        sayDo_cpp2v "-v -check-types -o ${base}_${ver}_cpp.v --templates ${base}_${ver}_cpp_templates.v ${input}${CRAM_CPP2VFLAGS:+ ${CRAM_CPP2VFLAGS}} -- -std=c++${ver}${CRAM_CXXFLAGS:+ ${CRAM_CXXFLAGS}} 2>&1 | sed 's/^ *[0-9]* | //'"
        sayDo "rocq c ${CHECK_CPP2V_ROCQC_ARGS} ${base}_${ver}_cpp_templates.v"
        sayDo "rocq c ${CHECK_CPP2V_ROCQC_ARGS} ${base}_${ver}_cpp.v"
    done
}

check_cpp2v_templates() {
    check_cpp2v_templates_versions "$1" 17
}
